def find_shorter_person(image):
    image_patch = ImagePatch(image)
    people_patches = image_patch.find("person")
    if not people_patches:
        return "No people found in the image."

    people_heights = []
    for person_patch in people_patches:
        height_info = person_patch.llm_query("How tall is this person?")
        try:
            height = coerce_to_numeric(height_info)
            people_heights.append((height, person_patch))
        except ValueError:
            continue

    if not people_heights:
        return "No height information available for any person."

    shortest_person, _ = min(people_heights, key=lambda x: x[0])
    return f"The shortest person is approximately {shortest_person} units tall."

